// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SigningMaker maker;
    FakeToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new SigningMaker();
        token = new FakeToken();
    }

    function testFuzz_property(uint256 ts, uint256 duration) public {
        vm.warp(bound(ts, 2, 86_400_000));
        duration = bound(duration, 1, block.timestamp - 1); // positive, no underflow in mutant

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + duration + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bool filled;
        try c.fillOrder(order, "", floorAssetTokenIds) {
            filled = true;
        } catch {
            filled = false;
        }

        bool exercised;
        if (filled) {
            exercised = maker.tryExercise(c, order);
        }

        // Rule: every successfully filled long order is exercisable immediately after filling.
        assertTrue(filled && exercised);
    }
}

contract SigningMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }

    function tryExercise(PuttyV2 c, PuttyV2.Order memory order) external returns (bool) {
        bool ok; try c.exercise(order, new uint256[](0)) { ok = true; } catch { ok = false; }
        return ok;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
